finalSourceCheck.command:
$root='D:\repos\teslasync'; $ErrorActionPreference='Stop'
'FINAL SOURCE CHECK UTC'; Get-Date -AsUTC -Format o
$files=@('web/src/features/system/pages/CommandReliabilityPage.tsx','web/src/features/system/lib/commandReliability.ts','web/src/features/system/components/statstrip-command-summaries/commandSummaryMetrics.tsx','web/src/api/hooks/useCommands.ts')
$patterns=[ordered]@{'static-inline-style-literal-var'='(?<![A-Za-z])style\s*=\s*\{\{[^}]*var\(--';'raw-html'='<\s*(button|input|textarea|select|table)\b';'direct-library-import'='from\s+[''\"](recharts|react-leaflet|framer-motion)[''\"]';'old-api-import'='from\s+[''\"](?:\.\./)+api[''\"]';'double-prefix'='/api/v1/';'camelcase-param'='[?&][A-Za-z_]*[a-z][A-Z][A-Za-z_]*=';'hidden-section'='\b(data|summary)\s*&&\s*<';'fetch-useeffect'='\b(fetch|useEffect)\s*\('}
foreach($e in $patterns.GetEnumerator()){$m=@(Select-String -LiteralPath ($files | ForEach-Object {Join-Path $root $_}) -Pattern $e.Value -CaseSensitive);'{0}|matches={1}' -f $e.Key,$m.Count}
$page=Get-Content "$root\web\src\features\system\pages\CommandReliabilityPage.tsx";'pageLines={0}' -f $page.Count;foreach($name in @('FadeIn','ChartContainer','GlassPanel','OperationalBrief','QueryError','EmptyState','HelpTooltip')){'{0}|count={1}' -f $name,@($page | Select-String -Pattern ('<'+$name+'\b') -CaseSensitive).Count}
'DECLARED TESTS / NOTRUN';foreach($f in @('web/src/features/system/pages/CommandReliabilityPage.test.tsx','web/src/features/system/lib/commandReliability.test.ts','web/src/features/system/components/statstrip-command-summaries/commandSummaryMetrics.test.ts','web/src/api/hooks/useCommands.test.tsx')){$m=@(Select-String -LiteralPath (Join-Path $root $f) -Pattern '^\s*it\(' -CaseSensitive);'{0}|declared={1}|executed=0|NOTRUN' -f $f,$m.Count;$m | ForEach-Object {'{0}:{1}' -f $_.LineNumber,$_.Line}}
$en=Get-Content "$root\web\src\i18n\en.json" -Raw | ConvertFrom-Json -AsHashtable;foreach($g in @('excellent','good','flaky','unreliable','unproven')){'commandReliability.grade.{0}|exists={1}' -f $g,($en['commandReliability'].Contains('grade') -and $en['commandReliability']['grade'].Contains($g))}
$q=Get-Content "$root\migration-queue.md";$q | Select-String -Pattern '^\|[^|]*\| 6 \| phase6-qa-system-command-reliability \|' | ForEach-Object {'{0}:{1}' -f $_.LineNumber,$_.Line};foreach($lit in @('commandSummaryMetrics','commandReliability.ts','commandReliability.grade','CommandReliabilityPage')){$m=@($q | Select-String -SimpleMatch $lit);'{0}|queueMatches={1}' -f $lit,$m.Count;$m | ForEach-Object {$c=$_.Line -split '\|';'{0}|{1}|{2}' -f $_.LineNumber,$c[1].Trim(),$c[3].Trim()}}
'TEST/LINT/BUILD/COMPILER/SERVER/BROWSER/NETWORK/API/VEHICLE/AUTH/PROVIDER EXECUTION=NOTRUN';'EXIT=0'
